namespace ClassicaCodex.Ingestion.MagicalPapyri;

/// <summary>One magical papyrus or amulet on papyri.info, as the setup step fetches it.</summary>
/// <param name="Source">"dclp" (Digital Corpus of Literary Papyri) or "ddbdp" (Duke Databank of Documentary Papyri).</param>
/// <param name="Id">The file's number: the TM number for DCLP, the HGV number for DDbDP.</param>
/// <param name="Path">Where the file sits in the papyri/idp.data repository.</param>
/// <param name="Label">How the text is cited: "PGM I", "Suppl. Mag. 42", "P.Oxy. 68 4672".</param>
/// <param name="Title">What it is, in English where the database's title was German.</param>
/// <param name="Gemf">Its number in Faraone and Torallas Tovar's Greek and Egyptian Magical Formularies (2022), if it has one.</param>
public sealed record MagicalPapyrus(string Source, string Id, string Path, string Label, string Title, string? Gemf);

